1	import { defineHook } from "../lib/hook";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import { PersistedRecord } from "../lib/persisted_record";
4	import { attachScrubber, fractionAt } from "../lib/scrubber";
5	import { scrollFollow } from "../lib/scroll_follow";
6	import { readerSettings } from "../lib/reader_settings_store";
7	import { cycleOption } from "../lib/cycle_option";
8	import { type WordTiming, parseWordTimings, wordSelector } from "../lib/types";
9	import { attachWordMenu } from "./word_menu";
10	
11	interface AudioPlayerDataset {
12	  audioUrl: string;
13	  timingsUrl: string;
14	  initialPosition?: string;
15	  bookTitle?: string;
16	  chapterTitle?: string;
17	  chapterId?: string;
18	  nextChapterId?: string;
19	  nextAudioUrl?: string;
20	  nextTimingsUrl?: string;
21	  nextChapterTitle?: string;
22	  prevChapterId?: string;
23	  prevAudioUrl?: string;
24	  prevTimingsUrl?: string;
25	  prevChapterTitle?: string;
26	}
27	
28	interface PlayerPrefs {
29	  readonly speed: number;
30	  readonly volume: number;
31	  readonly collapsed: boolean;
32	}
33	
34	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
35	  speed: 1,
36	  volume: 1,
37	  collapsed: false,
38	});
39	
40	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
41	
42	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
43	
44	const POSITION_REPORT_INTERVAL_MS = 5000;
45	const SKIP_SECONDS = 10;
46	const AUTO_SCROLL_GRACE_MS = 800;
47	
48	function coercePlayerPrefs(raw: unknown): Partial<PlayerPrefs> {
49	  if (!raw || typeof raw !== "object") return {};
50	  const r = raw as Record<string, unknown>;
51	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
52	  if (typeof r.speed === "number") out.speed = r.speed;
53	  if (typeof r.volume === "number") out.volume = r.volume;
54	  if (typeof r.collapsed === "boolean") out.collapsed = r.collapsed;
55	  return out;
56	}
57	
58	function migrateLegacyPlayerPrefs(): void {
59	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
60	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
61	  const legacyVolume = localStorage.getItem("readaloud-volume");
62	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
63	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
64	    return;
65	  const migrated: PlayerPrefs = {
66	    speed:
67	      legacySpeed !== null
68	        ? Number.parseFloat(legacySpeed)
69	        : PLAYER_PREFS_DEFAULTS.speed,
70	    volume:
71	      legacyVolume !== null
72	        ? Number.parseFloat(legacyVolume)
73	        : PLAYER_PREFS_DEFAULTS.volume,
74	    collapsed: legacyCollapsed === "true",
75	  };
76	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
77	}
78	
79	migrateLegacyPlayerPrefs();
80	const playerPrefs = new PersistedRecord<PlayerPrefs>(
81	  PLAYER_PREFS_KEY,
82	  PLAYER_PREFS_DEFAULTS,
83	  coercePlayerPrefs,
84	);
85	
86	function findActiveWord(
87	  timings: ReadonlyArray<WordTiming>,
88	  ms: number,
89	): number {
90	  let idx = -1;
91	  let lo = 0;
92	  let hi = timings.length - 1;
93	  while (lo <= hi) {
94	    const mid = (lo + hi) >>> 1;
95	    const t = timings[mid];
96	    if (!t) break;
97	    if (ms >= t.startMs && ms < t.endMs) {
98	      idx = mid;
99	      break;
100	    } else if (ms < t.startMs) {
101	      hi = mid - 1;
102	    } else {
103	      idx = mid;
104	      lo = mid + 1;
105	    }
106	  }
107	  if (idx >= 0 && idx < timings.length - 1) {
108	    const next = timings[idx + 1];
109	    if (next && ms >= next.startMs) idx += 1;
110	  }
111	  return idx;
112	}
113	
114	function formatTime(secs: number): string {
115	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
116	  const m = Math.floor(secs / 60);
117	  const s = Math.floor(secs % 60);
118	  return `${m}:${s < 10 ? "0" : ""}${s}`;
119	}
120	
121	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
122	  (ctx) => {
123	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
124	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
125	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
126	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
127	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
128	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
129	
130	    if (!audio || !playPauseBtn) return;
131	
132	    let timings: ReadonlyArray<WordTiming> = [];
133	    let currentWordIndex = -1;
134	    let lastReportedMs = -1;
135	    let rafId: number | undefined;
136	    let wordMenuCleanup: (() => void) | undefined;
137	    let intersectionObserver: IntersectionObserver | undefined;
138	
139	    const applyAudioPrefs = (): void => {
140	      const p = playerPrefs.get();
141	      audio.playbackRate = p.speed;
142	      audio.volume = p.volume;
143	      updateSpeedBadge(p.speed);
144	    };
145	
146	    const updateTimeDisplay = (): void => {
147	      if (!timeDisplay) return;
148	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
149	    };
150	
151	    const updateSpeedBadge = (speed: number): void => {
152	      if (!speedBadge) return;
153	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
154	    };
155	
156	    const setSpeed = (speed: number): void => {
157	      playerPrefs.set({ speed });
158	      audio.playbackRate = speed;
159	      updateSpeedBadge(speed);
160	    };
161	
162	    const cycleSpeed = (direction: "up" | "down"): void => {
163	      const closest = SPEEDS.reduce((best, s) =>
164	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
165	          ? s
166	          : best,
167	      );
168	      setSpeed(cycleOption(SPEEDS, closest, direction));
169	    };
170	
171	    const togglePlayback = (): void => {
172	      if (audio.paused) audio.play();
173	      else audio.pause();
174	    };
175	
176	    const seekToWordIndex = (idx: number): void => {
177	      const t = timings[idx];
178	      if (!t) return;
179	      audio.currentTime = t.startMs / 1000;
180	      if (audio.paused) audio.play();
181	    };
182	
183	    // Word highlighting with auto-scroll
184	    const highlightWord = (ms: number): void => {
185	      if (!textContainer || timings.length === 0) return;
186	      const idx = findActiveWord(timings, ms);
187	      if (idx === currentWordIndex) return;
188	
189	      if (currentWordIndex >= 0) {
190	        const old = textContainer.querySelector<HTMLElement>(
191	          wordSelector(currentWordIndex),
192	        );
193	        old?.classList.remove("word-active");
194	        old?.classList.add("word-spoken");
195	      }
196	
197	      if (idx >= 0) {
198	        const next = textContainer.querySelector<HTMLElement>(
199	          wordSelector(idx),
200	        );
201	        if (next) {
202	          next.classList.add("word-active");
203	          next.classList.remove("word-spoken");
204	
205	          if (!scrollFollow.get().autoScrollPaused) {
206	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
207	            next.scrollIntoView({ behavior: "smooth", block: "center" });
208	            if (intersectionObserver) {
209	              intersectionObserver.disconnect();
210	              intersectionObserver.observe(next);
211	            }
212	          }
213	        }
214	      }
215	
216	      if (idx > currentWordIndex) {
217	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
218	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
219	          if (el) {
220	            el.classList.remove("word-active");
221	            el.classList.add("word-spoken");
222	          }
223	        }
224	      } else if (idx >= 0 && idx < currentWordIndex) {
225	        for (let i = idx + 1; i <= currentWordIndex; i++) {
226	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
227	          if (el) el.classList.remove("word-spoken", "word-active");
228	        }
229	      }
230	
231	      currentWordIndex = idx;
232	    };
233	
234	    const startHighlightLoop = (): void => {
235	      const tick = (): void => {
236	        if (!audio.paused) {
237	          highlightWord(audio.currentTime * 1000);
238	          rafId = requestAnimationFrame(tick);
239	        }
240	      };
241	      rafId = requestAnimationFrame(tick);
242	    };
243	
244	    const stopHighlightLoop = (): void => {
245	      if (rafId !== undefined) {
246	        cancelAnimationFrame(rafId);
247	        rafId = undefined;
248	      }
249	    };
250	
251	    // Initial setup
252	    if (playerPrefs.get().collapsed) ctx.el.classList.add("collapsed");
253	
254	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
255	      "[data-volume-slider]",
256	    );
257	    if (volSlider) volSlider.value = String(playerPrefs.get().volume);
258	    updateSpeedBadge(playerPrefs.get().speed);
259	
260	    // The <audio> element has phx-update="ignore" so it's preserved across
261	    // chapter switches (push_patch) AND across LV reconnect/re-mount. The
262	    // hook itself, however, is destroyed and re-mounted on a re-mount —
263	    // so on mount we may find an <audio> element that's already loaded
264	    // (and possibly mid-playback) from a previous hook instance. In that
265	    // case we MUST NOT touch its src — doing so would interrupt the
266	    // user's listening session, which is exactly the bug we're chasing
267	    // with sleeping-mobile autoplay (LV WebSocket times out → re-mount on
268	    // wake → forced reload → 00:00/00:00).
269	    //
270	    // Heuristic: only set src if the element doesn't have one yet (or
271	    // has the page URL, the default for an unset <audio>). If it has
272	    // any other src — network URL, or a `blob:` URL prefetched by a
273	    // previous hook instance — leave it alone.
274	    const wantSrc = ctx.dataset.audioUrl;
275	    const existingSrc = audio.src;
276	    const hasMeaningfulSrc =
277	      existingSrc !== "" &&
278	      existingSrc !== window.location.href &&
279	      existingSrc !== window.location.origin + "/";
280	    if (!hasMeaningfulSrc) {
281	      audio.src = wantSrc;
282	      audio.load();
283	    }
284	    applyAudioPrefs();
285	
286	    ctx.on(audio, "loadedmetadata", () => {
287	      applyAudioPrefs();
288	      updateTimeDisplay();
289	      updateMediaSessionPosition();
290	    });
291	    ctx.on(audio, "durationchange", updateTimeDisplay);
292	
293	    // Word timings — fetched on mount and re-fetched whenever we swap to a
294	    // new chapter via swapToChapter().
295	    const fetchTimings = (url: string): void => {
296	      timings = [];
297	      currentWordIndex = -1;
298	      fetch(url)
299	        .then((r) => r.json())
300	        .then((data: unknown) => {
301	          timings = parseWordTimings(data);
302	          if (textContainer && !wordMenuCleanup)
303	            wordMenuCleanup = attachWordMenu(textContainer);
304	        })
305	        .catch((err: unknown) =>
306	          console.error("AudioPlayer: failed to load timings", err),
307	        );
308	    };
309	    fetchTimings(ctx.dataset.timingsUrl);
310	
311	    // Restore initial position — only on a fresh load. On re-mount of an
312	    // already-playing element we'd otherwise rewind the user back to a
313	    // saved position from a different LV session.
314	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
315	    if (initialMs > 0 && !hasMeaningfulSrc) {
316	      ctx.on(
317	        audio,
318	        "loadedmetadata",
319	        () => {
320	          audio.currentTime = initialMs / 1000;
321	        },
322	        { once: true },
323	      );
324	    }
325	
326	    // --- Media Session API ----------------------------------------------
327	    // Registers the OS-level lock-screen / notification controls. Without
328	    // this, a sleeping mobile device has no native "next chapter" button
329	    // and the WebSocket-bound LV nav often fails when the device wakes.
330	    // With this, the OS gives us a working next/prev button even when JS
331	    // is throttled, and the audio session keeps the lock screen UI alive
332	    // across chapter swaps (since we reuse the same <audio> element).
333	    const ms =
334	      typeof navigator !== "undefined" && "mediaSession" in navigator
335	        ? navigator.mediaSession
336	        : null;
337	
338	    const updateMediaSessionMetadata = (): void => {
339	      if (!ms) return;
340	      ms.metadata = new MediaMetadata({
341	        title: ctx.dataset.chapterTitle ?? "",
342	        artist: ctx.dataset.bookTitle ?? "",
343	        album: ctx.dataset.bookTitle ?? "",
344	      });
345	    };
346	
347	    const updateMediaSessionPosition = (): void => {
348	      if (!ms || !ms.setPositionState) return;
349	      if (!Number.isFinite(audio.duration) || audio.duration <= 0) return;
350	      try {
351	        ms.setPositionState({
352	          duration: audio.duration,
353	          position: Math.min(audio.currentTime, audio.duration),
354	          playbackRate: audio.playbackRate || 1,
355	        });
356	      } catch {
357	        // Some browsers throw on invalid positions; ignore.
358	      }
359	    };
360	
361	    // --- Next-chapter prefetch -----------------------------------------
362	    // Mobile browsers (iOS Safari especially) suspend network fetches
363	    // when the screen locks. If we wait until `ended` to fetch the next
364	    // chapter's audio, the request stalls and audio.play() never gets a
365	    // valid resource — exactly the bug we're chasing. So while the
366	    // current chapter is still playing (and the device presumably
367	    // awake), download the next chapter's audio fully into a Blob URL.
368	    // On `ended` we swap to the in-memory blob — no network needed.
369	    let currentBlobUrl: string | null = null; // points to in-use audio.src
370	    let prefetchedBlobUrl: string | null = null;
371	    let prefetchedFor: string | null = null;
372	    let prefetchAbort: AbortController | null = null;
373	
374	    const tryStartPrefetch = (): void => {
375	      if (!readerSettings.get().autoNextChapter) return;
376	      const url = ctx.dataset.nextAudioUrl;
377	      if (!url) return;
378	      // Already done or in flight for the same URL? Skip.
379	      if (prefetchedBlobUrl && prefetchedFor === url) return;
380	      if (prefetchAbort && prefetchedFor === url) return;
381	      // Target URL changed (e.g. user manually jumped chapters) — drop
382	      // any in-flight or stale-blob state and restart.
383	      if (prefetchAbort) {
384	        prefetchAbort.abort();
385	        prefetchAbort = null;
386	      }
387	      if (prefetchedBlobUrl) {
388	        URL.revokeObjectURL(prefetchedBlobUrl);
389	        prefetchedBlobUrl = null;
390	      }
391	      prefetchedFor = url;
392	      const abort = new AbortController();
393	      prefetchAbort = abort;
394	      fetch(url, { signal: abort.signal })
395	        .then((r) => {
396	          if (!r.ok) throw new Error(`HTTP ${r.status}`);
397	          return r.blob();
398	        })
399	        .then((blob) => {
400	          prefetchAbort = null;
401	          if (prefetchedFor !== url) return; // target changed mid-flight
402	          prefetchedBlobUrl = URL.createObjectURL(blob);
403	        })
404	        .catch((err: unknown) => {
405	          prefetchAbort = null;
406	          if ((err as Error)?.name !== "AbortError") {
407	            console.warn("AudioPlayer: next-chapter prefetch failed", err);
408	            // Reset prefetchedFor so we can retry later (e.g. on next
409	            // timeupdate) instead of being stuck thinking we're done.
410	            if (prefetchedFor === url) prefetchedFor = null;
411	          }
412	        });
413	    };
414	
415	    // Swap to a different chapter without unmounting the player. Used by
416	    // both the auto-next-on-ended path and (if invoked from outside) by
417	    // server-pushed chapter changes. Critically: same <audio> element, so
418	    // the OS audio session is preserved and lock-screen playback continues
419	    // without requiring a new user gesture.
420	    const swapToChapter = (
421	      audioUrl: string,
422	      timingsUrl: string,
423	      chapterTitle: string,
424	    ): void => {
425	      audio.src = audioUrl;
426	      audio.load();
427	      // Update title eagerly so the lock screen shows the new chapter name
428	      // even before the LV push_patch round-trip lands.
429	      if (ms) {
430	        ms.metadata = new MediaMetadata({
431	          title: chapterTitle,
432	          artist: ctx.dataset.bookTitle ?? "",
433	          album: ctx.dataset.bookTitle ?? "",
434	        });
435	      }
436	      fetchTimings(timingsUrl);
437	      audio.play().catch((err: unknown) => {
438	        console.warn("AudioPlayer: chapter-swap play blocked", err);
439	      });
440	    };
441	
442	    const goToNextChapter = (): boolean => {
443	      const networkUrl = ctx.dataset.nextAudioUrl;
444	      const timingsUrl = ctx.dataset.nextTimingsUrl;
445	      const title = ctx.dataset.nextChapterTitle ?? "";
446	      if (!networkUrl || !timingsUrl) return false;
447	
448	      // Use the prefetched in-memory blob if it's for THIS URL — this is
449	      // the whole point of prefetch and is what makes background-tab
450	      // autoplay actually work. Fall back to the network URL otherwise
451	      // (e.g. desktop user who never triggered prefetch).
452	      const useBlob =
453	        prefetchedBlobUrl !== null && prefetchedFor === networkUrl;
454	      const audioUrl = useBlob ? (prefetchedBlobUrl as string) : networkUrl;
455	
456	      // The blob currently in use as audio.src (if any) is being replaced
457	      // — revoke it so we don't leak ~tens of MB per chapter swap.
458	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
459	      currentBlobUrl = useBlob ? audioUrl : null;
460	      // Detach the prefetched-blob slot since it's now the current one
461	      // (or we didn't use it). Either way, the next prefetch (for the
462	      // chapter after this) starts fresh.
463	      prefetchedBlobUrl = null;
464	      prefetchedFor = null;
465	      if (prefetchAbort) {
466	        prefetchAbort.abort();
467	        prefetchAbort = null;
468	      }
469	
470	      swapToChapter(audioUrl, timingsUrl, title);
471	      // Tell the server to push_patch the URL + reload chapter assigns.
472	      // Fire-and-forget: if the WebSocket is asleep (locked phone), the
473	      // event queues until reconnect — audio playback doesn't depend on it.
474	      ctx.pushEvent("next_chapter");
475	      return true;
476	    };
477	
478	    const goToPrevChapter = (): boolean => {
479	      const url = ctx.dataset.prevAudioUrl;
480	      const timingsUrl = ctx.dataset.prevTimingsUrl;
481	      const title = ctx.dataset.prevChapterTitle ?? "";
482	      if (!url || !timingsUrl) return false;
483	      swapToChapter(url, timingsUrl, title);
484	      ctx.pushEvent("prev_chapter");
485	      return true;
486	    };
487	
488	    if (ms) {
489	      updateMediaSessionMetadata();
490	      const safeSet = (
491	        action: MediaSessionAction,
492	        handler: MediaSessionActionHandler | null,
493	      ): void => {
494	        try {
495	          ms.setActionHandler(action, handler);
496	        } catch {
497	          // Browser may not support this action — fine, skip it.
498	        }
499	      };
500	      safeSet("play", () => {
501	        audio.play().catch(() => {});
502	      });
503	      safeSet("pause", () => audio.pause());
504	      safeSet("seekbackward", (details) => {
505	        const delta = details.seekOffset ?? SKIP_SECONDS;
506	        audio.currentTime = Math.max(0, audio.currentTime - delta);
507	      });
508	      safeSet("seekforward", (details) => {
509	        const delta = details.seekOffset ?? SKIP_SECONDS;
510	        const max = Number.isFinite(audio.duration)
511	          ? audio.duration
512	          : Number.POSITIVE_INFINITY;
513	        audio.currentTime = Math.min(max, audio.currentTime + delta);
514	      });
515	      safeSet("seekto", (details) => {
516	        if (typeof details.seekTime === "number") {
517	          audio.currentTime = details.seekTime;
518	        }
519	      });
520	      // Only register next/prev when there's actually a target; otherwise
521	      // the OS UI shows greyed-out buttons (or nothing) which is correct.
522	      if (ctx.dataset.nextAudioUrl) {
