524	          goToNextChapter();
525	        });
526	      } else {
527	        safeSet("nexttrack", null);
528	      }
529	      if (ctx.dataset.prevAudioUrl) {
530	        safeSet("previoustrack", () => {
531	          goToPrevChapter();
532	        });
533	      } else {
534	        safeSet("previoustrack", null);
535	      }
536	      ctx.onDestroy(() => {
537	        // Clear handlers + metadata so a stale player on a different page
538	        // doesn't get media-key events meant for nothing.
539	        for (const a of [
540	          "play",
541	          "pause",
542	          "nexttrack",
543	          "previoustrack",
544	          "seekbackward",
545	          "seekforward",
546	          "seekto",
547	        ] as MediaSessionAction[]) {
548	          try {
549	            ms.setActionHandler(a, null);
550	          } catch {}
551	        }
552	        ms.metadata = null;
553	      });
554	    }
555	
556	    // Controls
557	    ctx.on(playPauseBtn, "click", togglePlayback);
558	
559	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
560	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
561	    if (skipBack) {
562	      ctx.on(skipBack, "click", () => {
563	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
564	      });
565	    }
566	    if (skipFwd) {
567	      ctx.on(skipFwd, "click", () => {
568	        const max = Number.isFinite(audio.duration)
569	          ? audio.duration
570	          : Number.POSITIVE_INFINITY;
571	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
572	      });
573	    }
574	
575	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
576	      "[data-collapse-toggle]",
577	    );
578	    if (collapseToggle) {
579	      ctx.on(collapseToggle, "click", () => {
580	        const isCollapsed = ctx.el.classList.toggle("collapsed");
581	        playerPrefs.set({ collapsed: isCollapsed });
582	      });
583	    }
584	
585	    if (volSlider) {
586	      ctx.on(volSlider, "input", () => {
587	        const vol = Number.parseFloat(volSlider.value);
588	        audio.volume = vol;
589	        playerPrefs.set({ volume: vol });
590	      });
591	    }
592	
593	    // Scrubbers (main + mini)
594	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
595	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
596	    const seekToFraction = (f: number): void => {
597	      if (Number.isFinite(audio.duration))
