614	    // playback progress, means we don't waste bandwidth on chapters the
615	    // user opens and immediately abandons.
616	    const PREFETCH_TRIGGER_FRACTION = 0.15;
617	    ctx.on(audio, "timeupdate", () => {
618	      if (!audio.duration) return;
