620	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
621	      if (fill) fill.style.width = `${pct}%`;
622	      const fillMini = ctx.el.querySelector<HTMLElement>(
623	        "[data-progress-fill-mini]",
624	      );
