626	      updateTimeDisplay();
627	
628	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
629	        tryStartPrefetch();
630	      }
631	
632	      const nowMs = Math.round(audio.currentTime * 1000);
633	      if (
634	        lastReportedMs < 0 ||
