662	        // JS-side chapter swap on the same <audio> element. This is the
663	        // critical path for sleeping-mobile autoplay: a full LV navigation
664	        // would tear down the OS audio session and silently fail when the
665	        // device is locked. Same-element src swap keeps the lock-screen
666	        // controls live and the audio session uninterrupted.
667	        goToNextChapter();
668	      }
669	    });
